package br.com.erp.product;
import br.com.erp.auth.*;
import br.com.erp.shared.*;
import br.com.erp.inventory.StockService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
@Service
public class BranchPricing {
 private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;private final StockService stock;
 public BranchPricing(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit,StockService stock){this.db=db;this.access=access;this.flow=flow;this.audit=audit;this.stock=stock;}
 public BigDecimal price(Actor a,UUID branch,UUID product,BigDecimal fallback){if(branch==null)return fallback;var rows=db.query("SELECT price FROM branch_price WHERE tenant_id=? AND branch_id=? AND product_id=?",(r,i)->r.getBigDecimal(1),a.tenantId(),branch,product);BigDecimal base=rows.isEmpty()?fallback:rows.getFirst();var day=java.time.LocalDate.now(java.time.ZoneId.of("America/Sao_Paulo"));var promos=db.query("SELECT percent FROM commercial_promotion WHERE tenant_id=? AND branch_id=? AND product_id=? AND active=TRUE AND starts_on<=? AND ends_on>=?",(r,i)->r.getBigDecimal(1),a.tenantId(),branch,product,day,day);return promos.isEmpty()?base:base.multiply(new BigDecimal("100").subtract(promos.getFirst())).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);}
 public record Input(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull UUID productId,@NotNull @Min(0) Long version,@NotNull @DecimalMin("0") @Digits(integer=17,fraction=2) BigDecimal price,@NotBlank @Size(min=5,max=500) String note){}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(Actor a,UUID branch,String query,int page,int size){access.requireBranch(a,branch);String where=" FROM product p LEFT JOIN branch_price b ON b.tenant_id=p.tenant_id AND b.product_id=p.id AND b.branch_id=? WHERE p.tenant_id=? AND (POSITION(LOWER(?) IN LOWER(p.name))>0 OR POSITION(LOWER(?) IN LOWER(p.sku))>0)";long total=db.queryForObject("SELECT COUNT(*)"+where,Long.class,branch,a.tenantId(),query,query);var rows=db.queryForList("SELECT p.id,p.sku,p.name,p.sale_price AS default_price,COALESCE(b.price,p.sale_price) AS price,COALESCE(b.version,0) AS version"+where+" ORDER BY p.name,p.id LIMIT ? OFFSET ?",branch,a.tenantId(),query,query,size,(long)page*size);if(stock.canSeeCost(a))for(var r:rows){BigDecimal cost=db.queryForObject("SELECT COALESCE(SUM(s.quantity*s.average_cost)/NULLIF(SUM(s.quantity),0),0) FROM stock_balance s JOIN warehouse w ON w.tenant_id=s.tenant_id AND w.id=s.warehouse_id WHERE s.tenant_id=? AND w.branch_id=? AND s.product_id=?",BigDecimal.class,a.tenantId(),branch,r.get("id"));BigDecimal price=(BigDecimal)r.get("price");r.put("average_cost",cost);r.put("margin_percent",price.signum()==0?null:price.subtract(cost).multiply(new BigDecimal("100")).divide(price,2,RoundingMode.HALF_UP));}return Map.of("items",rows,"total",total,"page",page,"size",size);}
 @Transactional public Map<String,Object> save(Actor a,Input input){flow.lock(a);access.requireBranch(a,input.branchId());String note=input.note().trim();if(note.length()<5)throw flow.bad("Justifique a alteração.");String hash=flow.hash("BRANCH_PRICE",input.branchId(),input.productId(),input.version(),input.price(),note);UUID old=flow.replay(a,input.requestId(),"BRANCH_PRICE",hash);if(old!=null)return Map.of("productId",old);var product=db.queryForList("SELECT sale_price FROM product WHERE tenant_id=? AND id=? AND active=TRUE FOR UPDATE",a.tenantId(),input.productId());if(product.isEmpty())throw flow.missing("Produto ativo não encontrado.");var rows=db.queryForList("SELECT price,version FROM branch_price WHERE tenant_id=? AND branch_id=? AND product_id=?",a.tenantId(),input.branchId(),input.productId());long version=rows.isEmpty()?0:((Number)rows.getFirst().get("version")).longValue();if(version!=input.version())throw flow.conflict("Preço alterado. Atualize.");BigDecimal previous=rows.isEmpty()?(BigDecimal)product.getFirst().get("sale_price"):(BigDecimal)rows.getFirst().get("price");if(rows.isEmpty())db.update("INSERT INTO branch_price(tenant_id,branch_id,product_id,price,version) VALUES(?,?,?,?,1)",a.tenantId(),input.branchId(),input.productId(),input.price());else db.update("UPDATE branch_price SET price=?,version=version+1 WHERE tenant_id=? AND branch_id=? AND product_id=?",input.price(),a.tenantId(),input.branchId(),input.productId());db.update("INSERT INTO branch_price_history(id,tenant_id,branch_id,product_id,old_price,new_price,note,created_by) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),a.tenantId(),input.branchId(),input.productId(),previous,input.price(),note,a.userId());flow.record(a,input.requestId(),"BRANCH_PRICE",hash,input.productId());audit.record(a,"BRANCH_PRICE_CHANGED",input.productId());return Map.of("productId",input.productId());}
 @Transactional(readOnly=true) public Map<String,Object> history(Actor a,UUID branch,UUID product,int page,int size){access.requireBranch(a,branch);return Map.of("items",db.queryForList("SELECT old_price,new_price,note,created_at,created_by FROM branch_price_history WHERE tenant_id=? AND branch_id=? AND product_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",a.tenantId(),branch,product,size,(long)page*size),"total",db.queryForObject("SELECT COUNT(*) FROM branch_price_history WHERE tenant_id=? AND branch_id=? AND product_id=?",Long.class,a.tenantId(),branch,product),"page",page,"size",size);}
}
@br.com.erp.shared.WorkflowAmounts @RestController @org.springframework.validation.annotation.Validated @RequestMapping("/api/v1/branch-prices") @PreAuthorize("hasAuthority('product:read')")
class BranchPriceController {
 private final BranchPricing service;BranchPriceController(BranchPricing service){this.service=service;}
 @GetMapping public Map<String,Object> list(@AuthenticationPrincipal Actor a,@RequestParam UUID branchId,@RequestParam(defaultValue="") @Size(max=200) String q,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return service.list(a,branchId,q,page,size);}
 @PutMapping @PreAuthorize("hasAuthority('product:read') and hasAuthority('product:write')") public Map<String,Object> save(@AuthenticationPrincipal Actor a,@Valid @RequestBody BranchPricing.Input input){return service.save(a,input);}
 @GetMapping("/history") public Map<String,Object> history(@AuthenticationPrincipal Actor a,@RequestParam UUID branchId,@RequestParam UUID productId,@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return service.history(a,branchId,productId,page,size);}
}
